const QUERIES = [
  'método fônico alfabetização',
  'dificuldade de leitura infantil',
  'alfabetização para pais dislexia'
];
const doisDiasAtras = new Date(Date.now() - 2*24*60*60*1000).toISOString();
return QUERIES.map(q => ({ json: { query: q, publishedAfter: doisDiasAtras } }));

const fs = require('fs');
const TENDENCIAS = 'C:\\Users\\usuario\\Desktop\\Projeto-professor-William\\auditoria\\tendencias-youtube.md';

const queries = $("Montar queries").all().map(i => i.json.query);
const respostas = $input.all().map(i => i.json);

const agora = new Date();
const pad = n => String(n).padStart(2, '0');
const dataStr = `${agora.getUTCFullYear()}-${pad(agora.getUTCMonth()+1)}-${pad(agora.getUTCDate())}`;
const horaStr = `${pad(agora.getUTCHours())}:${pad(agora.getUTCMinutes())}`;

let bloco = `\n## ${dataStr} ${horaStr} — n8n (automático, Tendências YouTube)\n\n`;
let totalVideos = 0;
for (let i = 0; i < queries.length; i++) {
  const query = queries[i];
  const resp = respostas[i] || {};
  const itens = Array.isArray(resp.items) ? resp.items : [];
  bloco += `### "${query}" (${itens.length} vídeo(s), últimos 2 dias)\n\n`;
  if (itens.length === 0) {
    bloco += 'Nenhum vídeo novo encontrado.\n\n';
    continue;
  }
  for (const v of itens) {
    const s = v.snippet || {};
    const id = (v.id && v.id.videoId) || '?';
    bloco += `- **${(s.title || '').replace(/\n/g, ' ')}** — ${s.channelTitle || '?'} (${s.publishedAt || '?'}) — https://www.youtube.com/watch?v=${id}\n`;
    totalVideos++;
  }
  bloco += '\n';
}

if (!fs.existsSync(TENDENCIAS)) {
  fs.writeFileSync(TENDENCIAS, '# Tendências YouTube — n8n\n\nGerado pelo workflow "Pesquisa de Tendências — YouTube". Dado bruto (título, canal, data, link) para a trilha de pesquisa de mercado usar — sem síntese de IA aqui, a leitura/julgamento fica com quem consumir este arquivo.\n' + bloco, 'utf8');
} else {
  fs.appendFileSync(TENDENCIAS, bloco, 'utf8');
}

return [{ json: { queries: queries.length, videos: totalVideos } }];
